// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before it cancels them.
const stopTimeout = 30 * time.Second

// entry is one enqueued job.
type entry struct {
	seq      uint64 // enqueue order
	job      Job
	cancel   context.CancelFunc // set while the job runs
	canceled bool               // Shutdown canceled the job's context
}

// Runner runs jobs on its workers.
type Runner struct {
	log       *slog.Logger
	workers   int
	queueSize int

	mu       sync.Mutex
	cond     *sync.Cond             // signaled when a job is queued or the runner starts stopping
	queue    []*entry               // jobs waiting to start, in enqueue order
	running  map[*entry]struct{}    // jobs whose workers are running them
	failed   []*entry               // jobs Shutdown canceled that returned an error
	nextSeq  uint64
	started  bool
	stopping bool

	wg   sync.WaitGroup // worker goroutines
	done chan struct{}  // closed when the first Shutdown call returns
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if queueSize < 0 {
		queueSize = 0
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{
		log:       log,
		workers:   workers,
		queueSize: queueSize,
		running:   map[*entry]struct{}{},
		done:      make(chan struct{}),
	}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing after Shutdown.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.started || r.stopping {
		return
	}
	r.started = true
	r.wg.Add(r.workers)
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for {
		e, ctx := r.next()
		if e == nil {
			return
		}
		r.runJob(e, ctx)
	}
}

// next waits for a queued job and marks it running. It returns nil once the runner is stopping,
// so jobs that have not started are left in the queue.
func (r *Runner) next() (*entry, context.Context) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for len(r.queue) == 0 && !r.stopping {
		r.cond.Wait()
	}
	if r.stopping {
		return nil, nil
	}
	e := r.queue[0]
	r.queue[0] = nil
	r.queue = r.queue[1:]
	ctx, cancel := context.WithCancel(context.Background())
	e.cancel = cancel
	r.running[e] = struct{}{}
	return e, ctx
}

func (r *Runner) runJob(e *entry, ctx context.Context) {
	_, err := r.call(ctx, e.job)
	e.cancel()
	if err != nil {
		r.log.Error("job failed", "job", e.job.Name, "err", err)
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	delete(r.running, e)
	if err != nil && e.canceled {
		r.failed = append(r.failed, e)
	}
}

// call runs j and recovers a panic, which it logs. A panicking job reports no error, so it is not kept
// for Pending.
func (r *Runner) call(ctx context.Context, j Job) (err error, _ bool) {
	return r.callRecovered(ctx, j)
}

func (r *Runner) callRecovered(ctx context.Context, j Job) (err error, panicked bool) {
	defer func() {
		if p := recover(); p != nil {
			panicked = true
			r.log.Error("job panicked", "job", j.Name, "panic", p, "stack", string(debug.Stack()))
		}
	}()
	return j.Run(ctx), false
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping {
		return ErrStopped
	}
	if len(r.queue) >= r.queueSize {
		return ErrQueueFull
	}
	r.nextSeq++
	r.queue = append(r.queue, &entry{seq: r.nextSeq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and jobs that have not
// started are not started. It waits for running jobs to finish. If ctx ends first, it cancels the context of
// every running job, waits for them to return, and returns ctx.Err(). Otherwise it returns nil.
//
// A job that ignores its context keeps Shutdown waiting, because Shutdown must not return while a job
// goroutine is still running. Later calls wait for the first call to finish, or until their own ctx ends.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.stopping {
		r.mu.Unlock()
		select {
		case <-r.done:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	r.stopping = true
	r.cond.Broadcast()
	r.mu.Unlock()
	defer close(r.done)

	idle := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(idle)
	}()

	select {
	case <-idle:
		return nil
	case <-ctx.Done():
	}

	r.mu.Lock()
	if len(r.running) == 0 {
		// Every job finished before ctx ended; the workers are on their way out.
		r.mu.Unlock()
		<-idle
		return nil
	}
	for e := range r.running {
		e.canceled = true
		e.cancel()
	}
	r.mu.Unlock()
	<-idle
	return ctx.Err()
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued jobs
// that have not started. After Shutdown they are the jobs that never started, followed by the jobs that Shutdown
// canceled and that returned an error. The caller can save them.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	failed := append([]*entry(nil), r.failed...)
	sort.Slice(failed, func(i, j int) bool { return failed[i].seq < failed[j].seq })

	out := make([]Job, 0, len(r.queue)+len(failed))
	for _, e := range r.queue {
		out = append(out, e.job)
	}
	for _, e := range failed {
		out = append(out, e.job)
	}
	return out
}

// Stop shuts the runner down like Shutdown, waiting up to 30 seconds for running jobs before it cancels them.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

