	r.stopping = true
	r.cond.Broadcast()
	r.mu.Unlock()
	defer close(r.done)

	idle := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(idle)
	}()

	select {
	case <-idle:
		return nil
	case <-ctx.Done():
