func TestPanickingJobIsRecoveredAndNotRerun(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var boomRuns atomic.Int32
	after := make(chan struct{})
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error {
		boomRuns.Add(1)
