	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan string, 1)
	if err := r.Enqueue(Job{Name: "a", Run: func(ctx context.Context) error {
		started <- "a"
		<-ctx.Done()
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := shutdownWithin(t, r, ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", jobNames(got))
	}
}

func TestShutdownNilWhenNothingRunning(t *testing.T) {
	r := NewRunner(2, 10, nil)
	r.Start()
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // already ended, but no job is running
	if err := shutdownWithin(t, r, ctx); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
}

func TestPendingBeforeShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started: queued jobs stay queued
	for _, name := range []string{"a", "b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: func(context.Context) error { return nil }}); err != nil {
			t.Fatal(err)
		}
	}
	if got := r.Pending(); !sameNames(got, "a", "b", "c") {
		t.Fatalf("Pending = %v, want [a b c]", jobNames(got))
	}
	if err := shutdownWithin(t, r, context.Background()); err != nil {
		t.Fatal(err)
	}
	if got := r.Pending(); !sameNames(got, "a", "b", "c") {
		t.Fatalf("Pending after Shutdown = %v, want [a b c]", jobNames(got))
	}
}

func TestPanickingJobIsRecoveredAndNotRerun(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var boomRuns atomic.Int32
	after := make(chan struct{})
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error {
		boomRuns.Add(1)
		panic("kaboom")
	}}); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(after)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-after:
	case <-time.After(5 * time.Second):
		t.Fatal("worker did not go on after a panic")
	}
	if err := shutdownWithin(t, r, context.Background()); err != nil {
		t.Fatal(err)
	}
	if n := boomRuns.Load(); n != 1 {
		t.Fatalf("panicking job ran %d times, want 1", n)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("Pending = %v, want none", jobNames(got))
	}
}

func TestSecondShutdownAndStopReturnAtOnce(t *testing.T) {
	r := NewRunner(2, 10, nil)
	r.Start()
	if err := shutdownWithin(t, r, context.Background()); err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	if err := shutdownWithin(t, r, context.Background()); err != nil {
		t.Fatalf("second Shutdown = %v, want nil", err)
	}
	r.Stop()
	if d := time.Since(start); d > time.Second {
		t.Fatalf("second Shutdown and Stop took %v", d)
	}
}

func TestStopWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var finished atomic.Bool
	started := make(chan struct{})
	if err := r.Enqueue(Job{Name: "a", Run: func(context.Context) error {
		close(started)
		time.Sleep(50 * time.Millisecond)
		finished.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	r.Stop()
	if !finished.Load() {
		t.Fatal("Stop returned before the running job finished")
	}
}

func TestEnqueueRacingShutdown(t *testing.T) {
	r := NewRunner(4, 100000, nil)
	r.Start()
	var mu sync.Mutex
	ran := map[string]bool{}
	accepted := map[string]bool{}
	var wg sync.WaitGroup
	for p := 0; p < 8; p++ {
		wg.Add(1)
		go func(p int) {
			defer wg.Done()
			for i := 0; i < 500; i++ {
				name := fmt.Sprintf("p%d-%d", p, i)
				err := r.Enqueue(Job{Name: name, Run: func(context.Context) error {
					mu.Lock()
					ran[name] = true
					mu.Unlock()
					return nil
				}})
				switch {
				case err == nil:
					mu.Lock()
					accepted[name] = true
					mu.Unlock()
				case errors.Is(err, ErrStopped):
					return
				default:
					t.Errorf("Enqueue = %v", err)
					return
				}
			}
		}(p)
	}
	time.Sleep(time.Millisecond)
	if err := shutdownWithin(t, r, context.Background()); err != nil {
		t.Fatal(err)
	}
	wg.Wait()

	// Every accepted job either ran or is still pending, and no job is both.
	pending := map[string]bool{}
	for _, j := range r.Pending() {
		pending[j.Name] = true
	}
	mu.Lock()
	defer mu.Unlock()
	for name := range accepted {
		if ran[name] == pending[name] {
			t.Fatalf("job %s: ran = %v, pending = %v; want exactly one", name, ran[name], pending[name])
		}
	}
	for name := range ran {
		if !accepted[name] {
			t.Fatalf("job %s ran but Enqueue did not accept it", name)
		}
	}
}

func TestNoGoroutinesLeftAfterShutdown(t *testing.T) {
	before := runtime.NumGoroutine()
	r := NewRunner(4, 10, nil)
	r.Start()
	started := make(chan string, 4)
	for i := 0; i < 4; i++ {
		if err := r.Enqueue(blocker(fmt.Sprint(i), started)); err != nil {
			t.Fatal(err)
		}
	}
	for i := 0; i < 4; i++ {
		<-started
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)
	defer cancel()
	if err := shutdownWithin(t, r, ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want context.DeadlineExceeded", err)
	}
	deadline := time.Now().Add(2 * time.Second)
	for runtime.NumGoroutine() > before {
		if time.Now().After(deadline) {
			t.Fatalf("goroutines = %d, want at most %d", runtime.NumGoroutine(), before)
		}
		time.Sleep(time.Millisecond)
	}
}
